import javax.xml.bind.JAXB
import javax.xml.transform.Source

class Bad {
    fun <T> unmarshal(src: Source, clazz: Class<T>): T = JAXB.unmarshal(src, clazz) // bad
}

import javax.xml.bind.JAXB
import java.io.StringWriter

class Bad2 {
    fun marshal(obj: Any, sw: StringWriter) = JAXB.marshal(obj, sw) // bad
}

import javax.xml.bind.JAXBContext

class Good {
    fun <T> unmarshal(src: javax.xml.transform.Source, clazz: Class<T>): T {
        val ctx = JAXBContext.newInstance(clazz)
        return ctx.createUnmarshaller().unmarshal(src) as T
    }
}
